51	import org.springframework.samples.petclinic.service.ClinicService;
52	import org.springframework.security.access.prepost.PreAuthorize;
53	import org.springframework.web.bind.annotation.CrossOrigin;
54	import org.springframework.web.bind.annotation.RequestMapping;
55	import org.springframework.web.bind.annotation.RestController;
56	import org.springframework.web.util.UriComponentsBuilder;
57	
58	import jakarta.transaction.Transactional;
59	
60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /**
70	     * A pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
71	     * and a dotted domain. Deliberately conservative so obviously malformed values (e.g. a bare
72	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
73	     */
74	    private static final Pattern EMAIL_PATTERN =
75	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
76	
77	    private final ClinicService clinicService;
78	
79	    private final OwnerMapper ownerMapper;
80	
81	    private final PetMapper petMapper;
82	
83	    private final VisitMapper visitMapper;
84	
85	    public OwnerRestControllerV1(ClinicService clinicService,
86	                                 OwnerMapper ownerMapper,
87	                                 PetMapper petMapper,
88	                                 VisitMapper visitMapper) {
89	        this.clinicService = clinicService;
90	        this.ownerMapper = ownerMapper;
91	        this.petMapper = petMapper;
92	        this.visitMapper = visitMapper;
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
98	        Collection<Owner> owners;
99	        if (lastName != null) {
100	            owners = this.clinicService.findOwnerByLastName(lastName);
101	        } else {
102	            owners = this.clinicService.findAllOwners();
103	        }
104	        if (owners.isEmpty()) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
113	        Owner owner = this.clinicService.findOwnerById(ownerId);
114	        if (owner == null) {
115	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
116	        }
117	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
123	        List<String> missingFields = new ArrayList<>();
124	        if (isBlank(ownerFieldsDto.getFirstName())) {
125	            missingFields.add("firstName");
126	        }
127	        if (isBlank(ownerFieldsDto.getLastName())) {
128	            missingFields.add("lastName");
129	        }
130	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
131	        if (isBlank(normalizedAddress)) {
132	            missingFields.add("address");
133	        }
134	        if (isBlank(ownerFieldsDto.getCity())) {
135	            missingFields.add("city");
136	        }
137	        if (isBlank(ownerFieldsDto.getTelephone())) {
138	            missingFields.add("telephone");
139	        }
140	        if (!missingFields.isEmpty()) {
141	            throw new MissingOwnerFieldsException(missingFields);
142	        }
143	        String city = ownerFieldsDto.getCity();
144	        long ownersInCity = this.clinicService.findAllOwners().stream()
145	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
146	            .count();
147	        if (ownersInCity >= 50) {
148	            throw new CityAtCapacityException(
149	                "the owner's city already contains 50 or more owners");
150	        }
151	        ownerFieldsDto.setAddress(normalizedAddress);
152	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
153	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
154	            .filter(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
155	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())))
156	            .toList();
157	        String householdId = null;
158	        if (!householdMembers.isEmpty()) {
159	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
160	                throw new DuplicateHouseholdException(
161	                    "an owner with the same last name and address already exists");
162	            }
163	            // Joining an existing household: share a stable identifier with every member,
164	            // backfilling any members created before the household was formed.
165	            householdId = householdId(lastName, normalizedAddress);
166	            for (Owner member : householdMembers) {
167	                if (!householdId.equals(member.getHouseholdId())) {
168	                    member.setHouseholdId(householdId);
169	                    this.clinicService.saveOwner(member);
170	                }
171	            }
172	        }
173	        String telephone = toE164(ownerFieldsDto.getTelephone());
174	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
175	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
176	        if (telephoneInUse) {
177	            throw new DuplicateTelephoneException(
178	                "an owner with the same E.164 telephone already exists");
179	        }
180	        ownerFieldsDto.setTelephone(telephone);
181	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
182	        HttpHeaders headers = new HttpHeaders();
183	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
184	        if (owner.getRegistrationDate() == null) {
185	            owner.setRegistrationDate(LocalDate.now());
186	        }
187	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
188	        owner.setHouseholdId(householdId);
189	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
190	        this.clinicService.saveOwner(owner);
191	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
192	        headers.setLocation(UriComponentsBuilder.newInstance()
193	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
194	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
200	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
201	        if (currentOwner == null) {
202	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
203	        }
204	        currentOwner.setAddress(ownerFieldsDto.getAddress());
205	        currentOwner.setCity(ownerFieldsDto.getCity());
206	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
207	        currentOwner.setLastName(ownerFieldsDto.getLastName());
208	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
209	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
210	        this.clinicService.saveOwner(currentOwner);
211	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
212	    }
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Transactional
216	    @Override
217	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
218	        Owner owner = this.clinicService.findOwnerById(ownerId);
219	        if (owner == null) {
220	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
221	        }
222	        this.clinicService.deleteOwner(owner);
223	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
224	    }
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
229	        Owner owner = this.clinicService.findOwnerById(ownerId);
230	        if (owner == null) {
231	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
232	        }
233	        HttpHeaders headers = new HttpHeaders();
234	        Pet pet = petMapper.toPet(petFieldsDto);
235	        owner.setId(ownerId);
236	        pet.setOwner(owner);
237	        pet.getType().setName(null);
238	        this.clinicService.savePet(pet);
239	        PetDto petDto = petMapper.toPetDto(pet);
240	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
241	            .buildAndExpand(pet.getId()).toUri());
242	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
243	    }
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
248	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
249	        if (currentOwner != null) {
250	            Pet currentPet = this.clinicService.findPetById(petId);
251	            if (currentPet != null) {
252	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
253	                currentPet.setName(petFieldsDto.getName());
254	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
255	                this.clinicService.savePet(currentPet);
256	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
257	            }
258	        }
259	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
260	    }
261	
262	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
263	    @Override
264	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
265	        HttpHeaders headers = new HttpHeaders();
266	        Visit visit = visitMapper.toVisit(visitFieldsDto);
267	        Pet pet = new Pet();
268	        pet.setId(petId);
269	        visit.setPet(pet);
270	        this.clinicService.saveVisit(visit);
271	        VisitDto visitDto = visitMapper.toVisitDto(visit);
272	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
273	            .buildAndExpand(visit.getId()).toUri());
274	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
275	    }
276	
277	
278	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
279	    @Override
280	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
281	        Owner owner = this.clinicService.findOwnerById(ownerId);
282	        if (owner != null) {
283	            Pet pet = owner.getPet(petId);
284	            if (pet != null) {
285	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
286	            }
287	        }
288	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
